import { Column, CreateDateColumn, PrimaryGeneratedColumn, UpdateDateColumn } from 'typeorm';

/*
 * Common fields shared by every application entity.
 *
 * Named AppBaseEntity so it never collides with TypeORM's own `BaseEntity` (active-record class).
 * - id         UUID, generated by PostgreSQL (gen_random_uuid()).
 * - createdAt  TIMESTAMPTZ, set on insert.
 * - updatedAt  TIMESTAMPTZ, refreshed on every update.
 * - isDelete   soft-delete flag. Ordinary DELETE operations set this to true (see BaseRepository).
 * - isActive   activation flag. Deactivation is a separate state from deletion.
 *
 * Timestamps are stored as TIMESTAMPTZ and the connection runs in UTC (database.config.ts).
 */
export abstract class AppBaseEntity {
  @PrimaryGeneratedColumn('uuid')
  id!: string;

  @CreateDateColumn({ type: 'timestamptz', name: 'createdAt' })
  createdAt!: Date;

  @UpdateDateColumn({ type: 'timestamptz', name: 'updatedAt' })
  updatedAt!: Date;

  @Column({ type: 'boolean', name: 'isDelete', default: false })
  isDelete!: boolean;

  @Column({ type: 'boolean', name: 'isActive', default: true })
  isActive!: boolean;
}
